import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import json
import warnings
warnings.filterwarnings('ignore')

# ── Style Setup ──────────────────────────────────────────────────────────────
plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 13,
    'axes.titleweight': 'bold',
    'axes.labelsize': 11,
    'figure.facecolor': 'white',
    'axes.facecolor': '#FAFAFA',
    'axes.edgecolor': '#E0E0E0',
    'grid.color': '#E8E8E8',
    'grid.linestyle': '--',
    'grid.alpha': 0.7,
})

BRAND_COLORS = {'Apple': '#007AFF', 'Garmin': '#00B386', 'Samsung': '#FF6B35'}
ACCENT = '#1E3A5F'
SECONDARY = '#6B7B8D'

# ── Helpers ──────────────────────────────────────────────────────────────────
def fig_to_base64(fig, dpi=150):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

def fmt_price(v):
    return f"${v:,.2f}"

def fmt_pct(v):
    return f"{v:.1f}%"

def fmt_corr(v):
    return f"{v:.3f}"

# ── Load Data ────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows, {df['brand'].nunique()} brands, {df['Country'].nunique()} countries")

# ── Pre-compute common aggregates ────────────────────────────────────────────
brand_stats = df.groupby('brand')['price'].agg(['mean', 'median', 'std', 'min', 'max', 'count']).round(2)
country_brand = df.groupby(['Country', 'brand'])['price'].median().unstack(fill_value=np.nan)
global_medians = df.groupby('brand')['price'].median()
case_df = df.dropna(subset=['Case_Size_mm'])
seller_vol = df.groupby('Seller_ID').size().rename('listings')
df_with_vol = df.merge(seller_vol, left_on='Seller_ID', right_index=True)
top5_pct_thresh = int(np.ceil(len(seller_vol) * 0.05))

# ── KPI Calculations ─────────────────────────────────────────────────────────
kpis = {}

# KPI 1: Median Listing Price by Brand
kpis['median_price_brand'] = {b: round(global_medians[b], 2) for b in global_medians.index}

# KPI 2: Geographic Price Spread
geo_spread = {}
for b in global_medians.index:
    medians = df[df['brand'] == b].groupby('Country')['price'].median()
    if len(medians) > 1:
        geo_spread[b] = round(medians.max() - medians.min(), 2)
    else:
        geo_spread[b] = 0
kpis['geo_spread'] = geo_spread

# KPI 3: Case Size Price Correlation
corr_overall = case_df['Case_Size_mm'].corr(case_df['price'])
corr_by_brand = {b: round(case_df[case_df['brand'] == b]['Case_Size_mm'].corr(case_df[case_df['brand'] == b]['price']), 3)
                 for b in df['brand'].unique() if len(case_df[case_df['brand'] == b]) > 2}
kpis['case_size_corr'] = {'overall': round(corr_overall, 3), 'by_brand': corr_by_brand}

# KPI 4: Power Seller Concentration
top_sellers = seller_vol.nlargest(top5_pct_thresh)
power_listings = top_sellers.sum()
total_listings = len(df)
kpis['power_seller_concentration'] = round(power_listings / total_listings * 100, 1)
kpis['power_seller_count'] = top5_pct_thresh
kpis['total_sellers'] = len(seller_vol)

# KPI 5: New vs Used Price Premium
premium = {}
for b in df['brand'].unique():
    new_p = df[(df['brand'] == b) & (df['condition'] == 'New')]['price'].mean()
    used_p = df[(df['brand'] == b) & (df['condition'] == 'Used')]['price'].mean()
    if pd.notna(new_p) and pd.notna(used_p) and used_p > 0:
        premium[b] = round((new_p - used_p) / used_p * 100, 1)
    else:
        premium[b] = None
kpis['new_used_premium'] = premium

print("KPIs computed:", json.dumps(kpis, indent=2))

