import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import json
import warnings
warnings.filterwarnings('ignore')

# ── Style Setup ──────────────────────────────────────────────────────────────
plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 13,
    'axes.titleweight': 'bold',
    'axes.labelsize': 11,
    'figure.facecolor': 'white',
    'axes.facecolor': '#FAFAFA',
    'axes.edgecolor': '#E0E0E0',
    'grid.color': '#E8E8E8',
    'grid.linestyle': '--',
    'grid.alpha': 0.7,
})

BRAND_COLORS = {'Apple': '#007AFF', 'Garmin': '#00B386', 'Samsung': '#FF6B35'}
ACCENT = '#1E3A5F'
SECONDARY = '#6B7B8D'

# ── Helpers ──────────────────────────────────────────────────────────────────
def fig_to_base64(fig, dpi=150):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

def fmt_price(v):
    return f"${v:,.2f}"

def fmt_pct(v):
    return f"{v:.1f}%"

def fmt_corr(v):
    return f"{v:.3f}"

# ── Load Data ────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows, {df['brand'].nunique()} brands, {df['Country'].nunique()} countries")

# ── Pre-compute common aggregates ────────────────────────────────────────────
brand_stats = df.groupby('brand')['price'].agg(['mean', 'median', 'std', 'min', 'max', 'count']).round(2)
country_brand = df.groupby(['Country', 'brand'])['price'].median().unstack(fill_value=np.nan)
global_medians = df.groupby('brand')['price'].median()
case_df = df.dropna(subset=['Case_Size_mm'])
seller_vol = df.groupby('Seller_ID').size().rename('listings')
df_with_vol = df.merge(seller_vol, left_on='Seller_ID', right_index=True)
top5_pct_thresh = int(np.ceil(len(seller_vol) * 0.05))

# ── KPI Calculations ─────────────────────────────────────────────────────────
kpis = {}

# KPI 1: Median Listing Price by Brand
kpis['median_price_brand'] = {b: round(global_medians[b], 2) for b in global_medians.index}

# KPI 2: Geographic Price Spread
geo_spread = {}
for b in global_medians.index:
    medians = df[df['brand'] == b].groupby('Country')['price'].median()
    if len(medians) > 1:
        geo_spread[b] = round(medians.max() - medians.min(), 2)
    else:
        geo_spread[b] = 0
kpis['geo_spread'] = geo_spread

# KPI 3: Case Size Price Correlation
corr_overall = case_df['Case_Size_mm'].corr(case_df['price'])
corr_by_brand = {b: round(case_df[case_df['brand'] == b]['Case_Size_mm'].corr(case_df[case_df['brand'] == b]['price']), 3)
                 for b in df['brand'].unique() if len(case_df[case_df['brand'] == b]) > 2}
kpis['case_size_corr'] = {'overall': round(corr_overall, 3), 'by_brand': corr_by_brand}

# KPI 4: Power Seller Concentration
top_sellers = seller_vol.nlargest(top5_pct_thresh)
power_listings = top_sellers.sum()
total_listings = len(df)
kpis['power_seller_concentration'] = round(power_listings / total_listings * 100, 1)
kpis['power_seller_count'] = top5_pct_thresh
kpis['total_sellers'] = len(seller_vol)

# KPI 5: New vs Used Price Premium
premium = {}
for b in df['brand'].unique():
    new_p = df[(df['brand'] == b) & (df['condition'] == 'New')]['price'].mean()
    used_p = df[(df['brand'] == b) & (df['condition'] == 'Used')]['price'].mean()
    if pd.notna(new_p) and pd.notna(used_p) and used_p > 0:
        premium[b] = round((new_p - used_p) / used_p * 100, 1)
    else:
        premium[b] = None
kpis['new_used_premium'] = premium

print("KPIs computed:", json.dumps(kpis, indent=2))

# ═══════════════════════════════════════════════════════════════════════════
# CHART GENERATION
# ═══════════════════════════════════════════════════════════════════════════

# ── Chart 1: Market Overview — Brand Distribution (donut) ────────────────────
fig1, ax1 = plt.subplots(figsize=(5, 5))
brand_counts = df['brand'].value_counts()
wedges, texts, autotexts = ax1.pie(
    brand_counts, labels=brand_counts.index, autopct='%1.1f%%',
    colors=[BRAND_COLORS.get(b, '#999') for b in brand_counts.index],
    startangle=90, pctdistance=0.78,
    wedgeprops=dict(width=0.45, edgecolor='white', linewidth=2)
)
for t in autotexts:
    t.set_fontsize(10)
    t.set_fontweight('bold')
ax1.set_title('Listings by Brand', pad=15)
chart1 = fig_to_base64(fig1)

# ── Chart 2: Market Overview — Condition Mix (stacked bar) ──────────────────
fig2, ax2 = plt.subplots(figsize=(7, 4))
cond_brand = df.groupby(['brand', 'condition']).size().unstack(fill_value=0)
cond_pct = cond_brand.div(cond_brand.sum(axis=1), axis=0) * 100
cond_colors = {'New': '#2ECC71', 'Used': '#E74C3C', 'Open box': '#F39C12', 'Refurbished': '#9B59B6'}
cond_brand_order = ['New', 'Used', 'Open box', 'Refurbished']
available_conds = [c for c in cond_brand_order if c in cond_pct.columns]
bottom = np.zeros(len(cond_pct))
for cond in available_conds:
    vals = cond_pct[cond].values
    ax2.bar(cond_pct.index, vals, bottom=bottom, label=cond,
            color=cond_colors.get(cond, '#999'), edgecolor='white', linewidth=0.5)
    bottom += vals
ax2.set_ylabel('Share of Listings (%)')
ax2.set_title('Condition Mix by Brand')
ax2.legend(loc='upper right', fontsize=9)
ax2.set_ylim(0, 105)
chart2 = fig_to_base64(fig2)

# ── Chart 3: Brand Pricing — Box Plot ───────────────────────────────────────
fig3, ax3 = plt.subplots(figsize=(7, 5))
brands_order = ['Apple', 'Garmin', 'Samsung']
box_data = [df[df['brand'] == b]['price'].values for b in brands_order]
bp = ax3.boxplot(box_data, labels=brands_order, patch_artist=True, widths=0.5,
                  medianprops=dict(color='#1E3A5F', linewidth=2),
                  whiskerprops=dict(color=SECONDARY),
                  capprops=dict(color=SECONDARY),
                  flierprops=dict(marker='o', markersize=3, alpha=0.4))
for patch, b in zip(bp['boxes'], brands_order):
    patch.set_facecolor(BRAND_COLORS.get(b, '#999'))
    patch.set_alpha(0.7)
ax3.set_ylabel('Listing Price (USD)')
ax3.set_title('Price Distribution by Brand')
ax3.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, p: f'${x:,.0f}'))
chart3 = fig_to_base64(fig3)

# ── Chart 4: Geographic Arbitrage — Heatmap ─────────────────────────────────
fig4, ax4 = plt.subplots(figsize=(10, 6))
# Compute deviation from global median per brand per country
country_brand_med = df.groupby(['Country', 'brand'])['price'].median().unstack()
deviation = country_brand_med.copy()
for b in deviation.columns:
    deviation[b] = ((deviation[b] - global_medians[b]) / global_medians[b]) * 100
deviation = deviation.dropna(how='all').sort_index()

# Plot as diverging bar chart (more readable than heatmap for this)
countries_sorted = deviation.index.tolist()
y_pos = np.arange(len(countries_sorted))
bar_height = 0.25

for i, b in enumerate(brands_order):
    if b in deviation.columns:
        vals = deviation[b].fillna(0).values
        colors = [BRAND_COLORS[b] if v >= 0 else BRAND_COLORS[b] for v in vals]
        alphas = [0.9 if v >= 0 else 0.5 for v in vals]
        bars = ax4.barh(y_pos + i * bar_height, vals, height=bar_height,
                        color=colors, alpha=0.8, edgecolor='none', label=b)
        # Add value labels
        for bar, val in zip(bars, vals):
            if abs(val) > 2:
                x_pos = bar.get_width() + (1.5 if val >= 0 else -1.5)
                ax4.text(x_pos, bar.get_y() + bar.get_height()/2,
                        f'{val:+.0f}%', va='center', ha='left' if val >= 0 else 'right',
                        fontsize=7.5, fontweight='bold', color=BRAND_COLORS[b])

ax4.axvline(0, color='#333', linewidth=0.8)
ax4.set_yticks(y_pos + bar_height)
ax4.set_yticklabels(countries_sorted, fontsize=9)
ax4.set_xlabel('Deviation from Global Median (%)')
ax4.set_title('Geographic Price Arbitrage — % Deviation from Brand Global Median')
ax4.legend(loc='lower right', fontsize=9)
ax4.invert_yaxis()
chart4 = fig_to_base64(fig4)

# ── Chart 5: Geographic — Median Price by Country and Brand (grouped bar) ───
fig5, ax5 = plt.subplots(figsize=(10, 6))
country_med = df.groupby(['Country', 'brand'])['price'].median().unstack()
country_med = country_med.dropna(how='all').sort_index()
x = np.arange(len(country_med))
width = 0.25
for i, b in enumerate(brands_order):
    if b in country_med.columns:
        ax5.bar(x + i * width, country_med[b].values, width, label=b,
                color=BRAND_COLORS[b], alpha=0.85, edgecolor='white', linewidth=0.5)
ax5.set_xticks(x + width)
ax5.set_xticklabels(country_med.index, rotation=45, ha='right', fontsize=9)
ax5.set_ylabel('Median Price (USD)')
ax5.set_title('Median Listing Price by Country & Brand')
ax5.legend(fontsize=9)
ax5.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, p: f'${x:,.0f}'))
chart5 = fig_to_base64(fig5)

# ── Chart 6: Case Size vs Price — Scatter with Trend ────────────────────────
fig6, ax6 = plt.subplots(figsize=(8, 5.5))
